  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 13, $j$4.1 Claims, Reasons and Evidence$j$, $j${"readings": [{"title": "Proverbs 18 (King James Version)", "url": "/portal/bible/Proverbs/18"}], "body": "An argument is a way of persuading with reasons. Every strong argument has a claim (the main point the writer wants you to accept), reasons (why the claim is true), and evidence (facts, examples, statistics, expert testimony or Scripture that support the reasons). Good readers separate the three and ask whether the evidence is relevant, which means it connects to the claim, and sufficient, which means there is enough of it.\n\nScripture values listening before judging. Proverbs 18:13 says, \"He that answereth a matter before he heareth it, it is folly and shame unto him.\" Read Proverbs 18 in the King James Version.\n\nRead this original argument:\n\nOur school should keep the library open one hour after classes. Students who stay late for tutoring or clubs have no quiet place to study. Last year, 41 of the 60 students surveyed said they did homework in a noisy hallway. A librarian can also help with research while the lab is open. Therefore, a longer library schedule would raise both grades and confidence.\n\nYour task: (1) Write the claim in your own words. (2) List two reasons. (3) Name the one piece of evidence that is a statistic. (4) Tell whether the evidence is relevant and sufficient, and what more you would want.\n\nFlorida standards: ELA.10.R.2.4, ELA.K12.EE.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.10.R.2.4, ELA.K12.EE.1.1", "script": "Listen, a good argument is not a loud argument. It is a well built one. Today we learn the three parts of every argument, so that you can find them when you read and use them when you write.\n\nThe first part is the claim. The claim is the main point the writer wants you to accept. The second part is the reasons. Reasons answer the question why. The third part is evidence. Evidence is the proof that backs up a reason. Evidence can be a fact, an example, a statistic, the words of an expert, or a passage of Scripture. Think of a table. The claim is the tabletop. The reasons are the legs. The evidence is the floor that holds the legs up. Take away the evidence and the table falls.\n\nNow watch this. A smart reader asks two questions about evidence. First, is it relevant? Relevant means it connects to the claim. A fact about basketball does not help a claim about libraries. Second, is it sufficient? Sufficient means there is enough of it. One story does not prove a rule for everyone.\n\nLook at my sample argument. The claim is that our school should keep the library open one hour after classes. The first reason is that students who stay late have no quiet place to study. The second reason is that a librarian could help with research. The evidence is the survey. Forty one of sixty students said they did homework in a noisy hallway. That is a statistic. Is it relevant? Yes, it connects to the lack of a quiet place. Is it sufficient? It is a good start, but sixty students is a small group, and nothing in the paragraph shows that grades or confidence would actually rise. So I would want more evidence about that last promise.\n\nNow Scripture. Proverbs chapter eighteen, verse thirteen says, He that answereth a matter before he heareth it, it is folly and shame unto him. That is a rule for readers. Hear the whole argument before you answer it. Many people argue against a claim they never fully heard.\n\nYour task today. Write the claim in your own words. List two reasons. Name the statistic. Then judge whether the evidence is relevant and sufficient, and say what more you would want. Take the four question check when you finish.\n\nA claim without evidence is only an opinion. Give the truth a foundation. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.1 Claims, Reasons and Evidence$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 14, $j$4.2 Ethos, Pathos and Logos$j$, $j${"readings": [{"title": "Acts 26 (King James Version)", "url": "/portal/bible/Acts/26"}], "body": "More than two thousand years ago a Greek teacher named Aristotle described three ways speakers persuade. Ethos is an appeal to credibility and character: why the audience should trust the speaker. Pathos is an appeal to emotion: stirring feelings such as hope, pity, anger or pride. Logos is an appeal to logic: facts, numbers and clear reasoning. Strong arguments usually blend all three, and careful readers ask whether each appeal is fair and honest.\n\nThe Apostle Paul used all three before King Agrippa. In Acts 26:25 he says, \"I am not mad, most noble Festus; but speak forth the words of truth and soberness.\" That is ethos, because he presents himself as sober and truthful. In Acts 26:27 he asks, \"King Agrippa, believest thou the prophets? I know that thou believest.\" That question is logos and pathos together, because it presses the king to follow his own belief. Agrippa answers in verse 28, \"Almost thou persuadest me to be a Christian.\" Read Acts 26 in the King James Version.\n\nRead this original speech excerpt from a school nurse urging students to wear helmets:\n\nFor twenty years I have cared for students after bicycle accidents. Helmets lower the chance of serious head injury by a large margin, according to national safety studies. I still remember a young man who walked out of my office alive because he had one on. Please do not let pride keep you from protection.\n\nYour task: Label one sentence ethos, one logos and one pathos, and explain each label.\n\nFlorida standards: ELA.10.R.3.4, ELA.K12.EE.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.10.R.3.4, ELA.K12.EE.1.1", "script": "Now, let us talk about the art of persuasion. People have studied it for thousands of years. A Greek teacher named Aristotle gave us three words that still help us today. Ethos. Pathos. Logos.\n\nEthos is the appeal to credibility and character. It answers the question, why should I trust this speaker? A doctor speaking about health, a veteran speaking about service, or a pastor speaking about faith may all draw on ethos. Pathos is the appeal to emotion. It stirs feelings such as hope, sadness, anger or pride. Logos is the appeal to logic. It uses facts, numbers and clear steps of reasoning.\n\nHere is the important lesson. Strong speakers blend all three. But a wise listener asks if each appeal is fair and honest. Ethos can be false if a person pretends to be an expert. Pathos can be false if a speaker only wants to frighten you. Logos can be false if the numbers are made up or misused.\n\nWatch this. Look at the Apostle Paul in Acts chapter twenty six. He stands before King Agrippa in chains. In verse twenty five he says, I am not mad, most noble Festus; but speak forth the words of truth and soberness. That is ethos. He is saying, I am sober and truthful, so you can trust me. In verse twenty seven he turns to the king and asks, King Agrippa, believest thou the prophets? I know that thou believest. That is a question built on logic, because the king already holds the premise, and it also touches his conscience, which is pathos. And look at the answer in verse twenty eight. Almost thou persuadest me to be a Christian. Paul's skill moved a king.\n\nNow look at my school nurse speech. For twenty years I have cared for students after bicycle accidents. That sentence is ethos, because her experience gives her credibility. Helmets lower the chance of serious head injury by a large margin, according to national safety studies. That is logos, because it relies on research. I still remember a young man who walked out of my office alive because he had one on. That is pathos, because a story moves the heart. Please do not let pride keep you from protection is the call to act.\n\nYour task today. Label one sentence ethos, one logos and one pathos, and explain each label. Take the four question check when you finish.\n\nPersuasion is power. Use it with honor and with love. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.2 Ethos, Pathos and Logos$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 15, $j$4.3 Evaluating Arguments and Spotting Fallacies$j$, $j${"readings": [{"title": "1 Thessalonians 5 (King James Version)", "url": "/portal/bible/1Thessalonians/5"}], "body": "A fallacy is a flaw in reasoning that can make a weak argument sound strong. Learning to spot fallacies protects you from being misled and keeps your own writing honest. Six common ones are:\n\nAd hominem: attacking the person instead of the argument. Example: \"Do not listen to her plan; she is new here.\"\nBandwagon: claiming something is right because many people do it. Example: \"Everyone is buying it, so it must be good.\"\nFalse dilemma: offering only two choices when more exist. Example: \"Either we cancel the field trip or we ruin the school year.\"\nHasty generalization: drawing a broad conclusion from too little evidence. Example: \"I met two rude drivers, so all drivers are rude.\"\nAppeal to fear: using fright instead of facts. Example: \"Vote for this rule or disaster will follow.\"\nSlippery slope: claiming one small step will lead to an extreme result with no proof. Example: \"If we allow a later bell, soon students will not come to school at all.\"\n\nScripture gives a better habit. 1 Thessalonians 5:21 says, \"Prove all things; hold fast that which is good.\" Read 1 Thessalonians 5 in the King James Version.\n\nYour task: (1) Name the fallacy in each example above. (2) Rewrite the hasty generalization as a fair claim with careful wording. (3) Explain what \"prove all things\" asks of a reader.\n\nFlorida standards: ELA.10.R.2.4, ELA.10.R.3.4, ELA.K12.EE.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.10.R.2.4, ELA.10.R.3.4, ELA.K12.EE.1.1", "script": "Listen, not every argument that sounds strong is strong. Some arguments shine on the outside and are empty on the inside. Today we learn to test arguments, and we learn the names of the most common flaws, which are called fallacies.\n\nA fallacy is a flaw in reasoning. It can trick the listener into agreeing when the proof is missing. Let us look at six.\n\nFirst, ad hominem. The Latin means to the person. The speaker attacks the person instead of the argument. Do not listen to her plan; she is new here. Being new does not make a plan wrong.\n\nSecond, the bandwagon. Everyone is buying it, so it must be good. A crowd can be wrong. The number of people does not prove the quality.\n\nThird, the false dilemma. Only two choices are offered when more exist. Either we cancel the field trip or we ruin the school year. There may be a dozen other options.\n\nFourth, the hasty generalization. A broad conclusion from too little evidence. I met two rude drivers, so all drivers are rude. Two is not enough.\n\nFifth, the appeal to fear. Using fright instead of facts. Vote for this rule or disaster will follow. A wise reader asks, what is the evidence for the disaster?\n\nSixth, the slippery slope. One small step is said to lead to an extreme result, with no proof for each step. If we allow a later bell, soon students will not come to school at all.\n\nNow watch this. The question to ask is not, do I like the conclusion? It is, does the evidence earn it? Scripture teaches this habit. First Thessalonians chapter five, verse twenty one says, Prove all things; hold fast that which is good. To prove means to test. A believer is not gullible. A believer tests the claim, and keeps what is true.\n\nLet us fix a hasty generalization. Instead of all drivers are rude, a careful writer says, in my experience on this road, I have met several rude drivers, though more evidence would help. Notice that the claim is smaller, but it is honest.\n\nYour task today. Name each fallacy in my examples. Rewrite the hasty generalization as a fair claim. Then explain what prove all things asks of a reader. Take the four question check when you finish.\n\nThe test of an argument is the truth, not the volume. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.3 Evaluating Arguments and Spotting Fallacies$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 16, $j$4.4 Writing an Argument with a Counterclaim$j$, $j${"readings": [{"title": "Isaiah 1 (King James Version)", "url": "/portal/bible/Isaiah/1"}], "body": "A strong written argument has a clear structure: an introduction with a claim, body paragraphs with reasons and evidence, a counterclaim that fairly states the opposing view, a rebuttal that answers it, and a conclusion that leaves the reader with something to remember. Addressing the other side makes you more credible. Isaiah 1:18 shows the posture of a good arguer: \"Come now, and let us reason together, saith the LORD.\" Read Isaiah 1 in the King James Version.\n\nProverbs 15:1 adds the tone: \"A soft answer turneth away wrath: but grievous words stir up anger.\"\n\nUse transitions to move the reader along: first, in addition, for example, however, on the other hand, therefore, in conclusion.\n\nRead this original model:\n\nClaim: Every student should learn a practical skill before graduation, such as cooking, basic budgeting or first aid.\nReason: These skills are used every day for life.\nEvidence: First aid training lets a teenager help in an emergency within minutes.\nCounterclaim: Some people say school time should be spent only on academic subjects.\nRebuttal: However, a student who can manage money and care for others uses academic skills better, because the lessons connect to real life.\nConclusion: Therefore, practical skills belong in every school.\n\nYour task: Write one argument paragraph of 6 to 8 sentences on a topic of your choice. Include a claim, one reason with evidence, a counterclaim, a rebuttal and a conclusion, with at least three transitions.\n\nFlorida standards: ELA.10.C.1.3, ELA.K12.EE.3.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.10.C.1.3, ELA.K12.EE.3.1", "script": "Now, let us put everything together. For three lessons you have learned to read arguments. Today you learn to write one that is clear, fair and strong.\n\nA written argument has a shape. It begins with an introduction that states the claim. Then come body paragraphs with reasons, each backed by evidence. Next comes something many students skip, the counterclaim. A counterclaim is the best point the other side would make. After it comes the rebuttal, which is your answer to that point. And last, a conclusion that brings the reader home.\n\nWhy include the other side? Because it makes you more credible. If you only tell one side, the reader wonders what you are hiding. If you state the other side fairly and answer it, the reader trusts you. That is ethos in action.\n\nScripture models this posture. Isaiah chapter one, verse eighteen says, Come now, and let us reason together, saith the LORD. God invites reasoning. And Proverbs fifteen, verse one gives the tone. A soft answer turneth away wrath: but grievous words stir up anger. You can disagree strongly and still speak kindly.\n\nWatch this. Transitions are the bridges between ideas. First and in addition add reasons. For example introduces evidence. However and on the other hand introduce a counterclaim. Therefore and in conclusion lead to the ending.\n\nNow look at my model. The claim is that every student should learn a practical skill before graduation, such as cooking, basic budgeting or first aid. The reason is that these skills are used every day for life. The evidence is that first aid training lets a teenager help in an emergency within minutes. The counterclaim is that some say school time should be spent only on academic subjects. The rebuttal begins with however, and says a student who can manage money and care for others uses academic skills better, because the lessons connect to real life. The conclusion begins with therefore. Notice that the tone is respectful. I did not insult anyone who disagrees.\n\nYour task today. Write one argument paragraph of six to eight sentences on a topic of your choice. Include a claim, one reason with evidence, a counterclaim, a rebuttal and a conclusion, and use at least three transitions. Take the four question check when you finish.\n\nTo argue well is to love the truth and the listener. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.4 Writing an Argument with a Counterclaim$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Assessment 4: Write an Argument$j$, $j${"prompt": "Write a short argumentative essay of three to four paragraphs on one of these questions, or on a topic your teacher approves: Should every high school student be required to volunteer in the community? Should schools start later in the morning? Should students learn a trade or practical skill before graduating?\n\nYour essay must include: an introduction with a clear claim; at least two reasons, each supported by evidence (a fact, an example, a number or Scripture); one counterclaim stated fairly; a rebuttal; at least one use of ethos, pathos or logos that you can name; and a conclusion. Avoid fallacies. Use transitions and a respectful tone. Length: 300 to 400 words.", "rubric": "100 points. Clear claim: 15 points. Two reasons with relevant, sufficient evidence: 25 points. Counterclaim and rebuttal: 20 points. Use of rhetorical appeals and avoidance of fallacies: 15 points. Organization, transitions and tone: 15 points. Grammar and conventions: 10 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 4: Write an Argument$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 4, $j$Discussion 4: A Good Argument Heard$j$, $j${"prompt": "Describe a time when someone changed your mind, or when you changed someone else's mind, with a good argument. Write a post of at least 120 words that (1) tells what the issue was, (2) names the claim, one reason and the evidence that was used, (3) tells which appeal, ethos, pathos or logos, was most powerful and why, and (4) tells how the person's tone affected you. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why does a gentle tone often persuade better than a loud one? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 4: A Good Argument Heard$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Check 4.1: Claims, Reasons and Evidence$j$, $j${"questions": [{"q": "The claim of an argument is:", "options": ["The last sentence only", "The title of the book", "A list of dates", "The main point the writer wants you to accept"]}, {"q": "Evidence is relevant when it:", "options": ["Connects directly to the claim", "Is about a different subject", "Is the writer's favorite", "Is very long"]}, {"q": "Evidence is sufficient when:", "options": ["It is hard to read", "It is only one story", "There is enough of it to support the reason", "It is repeated three times"]}, {"q": "In the library argument, the survey of 60 students is an example of:", "options": ["A caption", "A theme", "A simile", "A statistic"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Claims, Reasons and Evidence$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,2,3}'::int[], array[$j$The claim is the main point of the argument.$j$,$j$Relevant evidence connects to the claim.$j$,$j$Sufficient means there is enough evidence.$j$,$j$A number drawn from a survey is a statistic.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Claims, Reasons and Evidence$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 17, $j$Check 4.2: Ethos, Pathos and Logos$j$, $j${"questions": [{"q": "Ethos is an appeal to:", "options": ["Logic only", "Emotion", "Rhyme", "Credibility and character"]}, {"q": "Pathos is an appeal to:", "options": ["Emotion", "The speaker's title", "Statistics only", "Grammar"]}, {"q": "Logos is an appeal to:", "options": ["Humor only", "Popularity", "Fear alone", "Logic, facts and reasoning"]}, {"q": "When Paul says 'I am not mad, most noble Festus; but speak forth the words of truth and soberness,' he mainly uses:", "options": ["A statistic", "Ethos", "A flashback", "A rhyme"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Ethos, Pathos and Logos$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,3,1}'::int[], array[$j$Ethos builds trust in the speaker.$j$,$j$Pathos stirs feelings.$j$,$j$Logos relies on facts and clear reasoning.$j$,$j$He presents himself as truthful and sober.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Ethos, Pathos and Logos$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 18, $j$Check 4.3: Evaluating Arguments and Spotting Fallacies$j$, $j${"questions": [{"q": "Attacking the person instead of the argument is called:", "options": ["Bandwagon", "Slippery slope", "Ad hominem", "Logos"]}, {"q": "'Either we cancel the trip or we ruin the year' is an example of:", "options": ["Evidence", "A false dilemma", "A simile", "A statistic"]}, {"q": "'I met two rude drivers, so all drivers are rude' is a:", "options": ["Central idea", "Hasty generalization", "Theme", "Counterclaim"]}, {"q": "1 Thessalonians 5:21 encourages readers to:", "options": ["Argue loudly", "Test all things and hold fast what is good", "Avoid all reading", "Accept every claim"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Evaluating Arguments and Spotting Fallacies$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,1,1}'::int[], array[$j$Ad hominem attacks the person, not the argument.$j$,$j$It offers only two choices when more exist.$j$,$j$The conclusion is too broad for the evidence.$j$,$j$To prove all things means to test them.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Evaluating Arguments and Spotting Fallacies$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 19, $j$Check 4.4: Writing an Argument with a Counterclaim$j$, $j${"questions": [{"q": "A counterclaim is:", "options": ["A statistic", "The best point of the opposing view", "The writer's conclusion", "A title"]}, {"q": "A rebuttal is:", "options": ["A list of sources", "The introduction", "A rhyme", "Your answer to the counterclaim"]}, {"q": "Which transition best introduces a counterclaim?", "options": ["In addition", "For example", "However", "First"]}, {"q": "Why include the other side in an argument?", "options": ["It hides the claim", "It makes the paper shorter", "It builds credibility with the reader", "It is never needed"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Writing an Argument with a Counterclaim$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,2,2}'::int[], array[$j$A counterclaim states the opposing view.$j$,$j$A rebuttal answers the other side.$j$,$j$However signals a contrast.$j$,$j$Answering the other side makes you more trustworthy.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Writing an Argument with a Counterclaim$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 20, $j$Unit Quiz 4: Rhetoric and Argument$j$, $j${"questions": [{"q": "An argument is built from:", "options": ["A claim, reasons and evidence", "A rhyme scheme", "Only a title", "Only dates"]}, {"q": "Evidence that connects directly to the claim is:", "options": ["Relevant", "Biased", "Poetic", "Sufficient"]}, {"q": "Appealing to a speaker's credibility is called:", "options": ["Pathos", "Ethos", "Logos", "Irony"]}, {"q": "A story that stirs the audience's feelings is mainly:", "options": ["Pathos", "Logos", "A fallacy", "A rebuttal"]}, {"q": "Using facts, numbers and clear reasoning is:", "options": ["Logos", "Pathos", "A counterclaim", "Ethos"]}, {"q": "'Everyone is buying it, so it must be good' is:", "options": ["A statistic", "A bandwagon appeal", "A theme", "A rebuttal"]}, {"q": "In an argument, the rebuttal:", "options": ["Ends the essay with a rhyme", "Lists the sources", "Repeats the title", "Answers the counterclaim"]}, {"q": "Proverbs 15:1 teaches that a soft answer:", "options": ["Wins by volume", "Avoids all reasoning", "Starts a quarrel", "Turns away wrath"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Rhetoric and Argument$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,1,0,0,1,3,3}'::int[], array[$j$Claim, reasons and evidence make an argument.$j$,$j$Relevant evidence connects to the claim.$j$,$j$Ethos is the appeal to credibility.$j$,$j$Pathos appeals to emotion.$j$,$j$Logos appeals to logic.$j$,$j$A crowd does not prove quality.$j$,$j$The rebuttal responds to the opposing view.$j$,$j$A soft answer turneth away wrath.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Rhetoric and Argument$j$ on conflict (item_id) do nothing;
